```cpp
#include <iostream>
using namespace std;

int main() {
    char ch;

    cout << "Enter an alphabet: ";
    cin >> ch;

    // Check if vowel or consonant
    if (ch == 'a' || ch == 'e' || ch == 'i' || ch == 'o' || ch == 'u' ||
        ch == 'A' || ch == 'E' || ch == 'I' || ch == 'O' || ch == 'U') {
        cout << "Vowel" << endl;
    } else {
        cout << "Consonant" << endl;
    }

    // Check if lowercase or uppercase
    if (ch >= 'a' && ch <= 'z') {
        cout << "Lowercase" << endl;
    } else if (ch >= 'A' && ch <= 'Z') {
        cout << "Uppercase" << endl;
    }

    return 0;
}
```

