}

Alternatively, using while loop:

#include <iostream>
using namespace std;

int main() {
    int num = 2;
    while (num <= 11) {
        cout << num << ", ";
        num += 3;
    }
    return 0;
}

int a=0, b=1, c;
while(a <= 8) {
  cout << a << ", ";
  c = a + b;
  a = b;
  b = c;
}
Alternatively, the condition can be modified to while(a < 8) or the output statement can include comma and space formatting. The key is to print 'a' before updating its value, and ensure the loop prints values up to 8.

