```python
def factorial(n):
    if n < 0:
        raise ValueError("n must be non-negative")
    result = 1
    for value in range(2, n + 1):
        result *= value
    return result

for value in [0, 1, 2, 5, 7]:
    print(value, factorial(value))
```
The five tests print 1, 1, 2, 120, and 5040.

```python
class Rectangle:
    def __init__(self, length, width):
        self.length = length
        self.width = width
    def area(self):
        return self.length * self.width
    def perimeter(self):
        return 2 * (self.length + self.width)

r = Rectangle(8, 3)
print(r.area())
print(r.perimeter())
```
The class stores the dimensions and its methods calculate area and perimeter.

```python
def add_values(values):
    return sum(values)

def remove_repeated(values):
    return list(dict.fromkeys(values))

def average(values):
    return add_values(values) / len(values)

values = [2, 4, 4, 6]
print(average(values))
print(average(remove_repeated(values)))
```
Separate functions make each operation easier to test and reuse.

```cpp
#include <iostream>
using namespace std;

int main() {
    int totalSeconds, hours, minutes, seconds;

    cout << "Enter time in seconds: ";
    cin >> totalSeconds;

    hours = totalSeconds / 3600;
    totalSeconds = totalSeconds % 3600;

    minutes = totalSeconds / 60;
    seconds = totalSeconds % 60;

    cout << hours << " hour(s) " << minutes << " minute(s) and " 
         << seconds << " second(s)" << endl;

    return 0;
}
```

